// Hand-built low-poly squire and weapon props
function makeKnight(isPlayer=false){const root=new THREE.Group(),body=new THREE.Group();root.add(body);scene.add(root);const team=isPlayer?blue:red;
 cylinder(body,0,.82,0,.38,.32,.72,team);box(body,0,1.08,0,.68,.22,.35,steel);cylinder(body,0,1.48,0,.27,.25,.42,steel,8);const helmet=new THREE.Mesh(new THREE.IcosahedronGeometry(.34,1),isPlayer?gold:steel);helmet.position.set(0,1.76,0);helmet.scale.y=.85;helmet.castShadow=true;body.add(helmet);box(body,0,1.69,.29,.28,.09,.08,darkStone);box(body,1*.39,1.36,0,.18,.52,.2,team);box(body,-.39,1.36,0,.18,.52,.2,team);
 for(const x of [-.2,.2]){cylinder(body,x,.38,0,.12,.15,.65,leather,6);box(body,x,.12,.08,.23,.16,.38,steel)}
 // helmet crest
 if(isPlayer){box(body,0,2.1,0,.1,.3,.16,red);}
 const weapon=new THREE.Group();weapon.position.set(.56,1.35,.2);body.add(weapon);
 const sword=new THREE.Group();weapon.add(sword);cylinder(sword,0,-.05,0,.055,.055,.36,leather,6);const blade=new THREE.Mesh(new THREE.BoxGeometry(.09,.8,.06),steel);blade.position.y=.48;blade.castShadow=true;sword.add(blade);const tip=new THREE.Mesh(new THREE.ConeGeometry(.065,.22,4),steel);tip.position.y=1;sword.add(tip);box(sword,0,.08,0,.36,.07,.09,gold);
 const flail=new THREE.Group();weapon.add(flail);cylinder(flail,0,.2,0,.06,.055,.48,leather,6);const chain=new THREE.Mesh(new THREE.CylinderGeometry(.025,.025,.7,6),steel);chain.position.y=.68;flail.add(chain);const ball=new THREE.Mesh(new THREE.IcosahedronGeometry(.25,1),steel);ball.position.y=1.08;ball.castShadow=true;flail.add(ball);for(let i=0;i<6;i++){const spike=new THREE.Mesh(new THREE.ConeGeometry(.055,.18,4),steel);spike.position.set(Math.sin(i*Math.PI/3)*.22,1.08+Math.cos(i*Math.PI/3)*.18,0);spike.rotation.z=Math.PI/2-i*Math.PI/3;flail.add(spike)}
 const bow=new THREE.Group();weapon.add(bow);const arc=new THREE.Mesh(new THREE.TorusGeometry(.44,.045,5,12,Math.PI),wood);arc.rotation.z=-Math.PI/2;arc.position.y=.45;bow.add(arc);const string=new THREE.Mesh(new THREE.CylinderGeometry(.012,.012,.82,4),cloth);string.position.set(0,.45,0);bow.add(string);box(bow,0,.45,.02,.055,.78,.045,wood);
 return {root,body,weapon,models:{sword,flail,bow},isPlayer,hp:isPlayer?100:38,maxHp:isPlayer?100:38,attackTimer:0,hitFlash:0,dead:false,walk:0};}
const player=makeKnight(true);player.root.position.set(0,0,5);player.weaponType='sword';
let enemies=[],arrows=[],particles=[];let running=false,gameOver=false,wave=1,kills=0,waveTotal=4,spawnTimer=0,attackCooldown=0,dodgeTimer=0,dodgeCooldown=0,weaponSwing=0;const keys={},move={x:0,z:0};let lastTime=performance.now();
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function spawnEnemy(){const edge=Math.floor(Math.random()*4),p=edge===0?[-14,-12-Math.random()*3]:edge===1?[14,-12-Math.random()*3]:edge===2?[-14+Math.random()*28,-13]:[14-Math.random()*28,-13];const e=makeKnight(false);e.root.position.set(p[0],0,p[1]);e.hp=e.maxHp=wave===1?38:wave===2?48:58;e.attackTimer=Math.random()*.6;e.speed=wave===3?1.5:1.3;enemies.push(e);}
function startWave(){waveTotal=wave===1?4:wave===2?5:6;for(let i=0;i<Math.min(3,waveTotal);i++)spawnEnemy();spawnTimer=1;updateHUD();toast(`WAVE ${wave}`)}
function selectWeapon(type){player.weaponType=type;for(const b of document.querySelectorAll('.weapon'))b.classList.toggle('active',b.dataset.weapon===type);Object.entries(player.models).forEach(([key,m])=>m.visible=key===type)}
selectWeapon('sword');document.querySelectorAll('.weapon').forEach((b,i)=>b.addEventListener('click',()=>selectWeapon(b.dataset.weapon)));window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Digit1')selectWeapon('sword');if(e.code==='Digit2')selectWeapon('flail');if(e.code==='Digit3')selectWeapon('bow');if(e.code==='Space')dodge()});window.addEventListener('keyup',e=>keys[e.code]=false);renderer.domElement.addEventListener('pointerdown',()=>attack());
function attack(){if(!running||gameOver||attackCooldown>0)return;attackCooldown=player.weaponType==='bow'?.52:player.weaponType==='flail'?.75:.43;weaponSwing=.38;
 if(player.weaponType==='bow'){const dir=new THREE.Vector3(Math.sin(player.root.rotation.y),0,Math.cos(player.root.rotation.y));const mesh=new THREE.Mesh(new THREE.CylinderGeometry(.025,.025,.62,5),wood);mesh.rotation.x=Math.PI/2;mesh.position.copy(player.root.position).add(new THREE.Vector3(0,1.45,0)).addScaledVector(dir,.75);scene.add(mesh);arrows.push({mesh,dir:dir.normalize(),life:2,damage:27,owner:'player'});return}
 const range=player.weaponType==='flail'?3.25:2.05;const dir=new THREE.Vector3(Math.sin(player.root.rotation.y),0,Math.cos(player.root.rotation.y));let struck=false;for(const e of enemies){if(e.dead)continue;const d=e.root.position.clone().sub(player.root.position);const forward=d.x*dir.x+d.z*dir.z;if(d.length()<range&&forward>.0){damageEnemy(e,player.weaponType==='flail'?31:25);struck=true}}
 if(struck)spawnBurst(player.root.position,0xe8c06a,5);
}
function dodge(){if(!running||dodgeCooldown>0)return;dodgeTimer=.28;dodgeCooldown=1.2;const dx=move.x||Math.sin(player.root.rotation.y),dz=move.z||Math.cos(player.root.rotation.y);player.root.position.x+=dx*.8;player.root.position.z+=dz*.8;}
function damageEnemy(e,n){if(e.dead)return;e.hp-=n;e.hitFlash=.14;if(e.hp<=0){e.dead=true;kills++;spawnBurst(e.root.position,0xc99454,12);scene.remove(e.root);const idx=enemies.indexOf(e);if(idx>=0)enemies.splice(idx,1);if(kills%3===0&&player.hp<100){player.hp=Math.min(100,player.hp+12);toast('RATIONS +12 VITALITY')}updateHUD();}}
function enemyAttack(e){if(e.attackTimer>0)return;const d=e.root.position.distanceTo(player.root.position);if(d<1.6){e.attackTimer=1.15;player.hp-=wave===3?12:9;document.querySelector('#damage').style.boxShadow='inset 0 0 110px #e43c2d99';setTimeout(()=>document.querySelector('#damage').style.boxShadow='inset 0 0 100px #e43c2d00',130);updateHUD();if(player.hp<=0)endGame(false)}}
function spawnBurst(pos,color,count){for(let i=0;i<count;i++){const m=new THREE.Mesh(new THREE.IcosahedronGeometry(.06+Math.random()*.09,0),mat(color));m.position.copy(pos).add(new THREE.Vector3(0,.8,0));scene.add(m);particles.push({mesh:m,vel:new THREE.Vector3((Math.random()-.5)*4,Math.random()*4,(Math.random()-.5)*4),life:.5+Math.random()*.5})}}
function updateHUD(){document.querySelector('#healthNum').textContent=Math.max(0,Math.ceil(player.hp));document.querySelector('#healthFill').style.width=`${Math.max(0,player.hp)}%`;document.querySelector('#wave').textContent=`WAVE ${wave} / 3`;const remaining=(waveTotal-(kills-([0,4,9][wave-1]||0)));document.querySelector('#subobjective').textContent=`${Math.max(0,remaining)} / ${waveTotal} REMAINING`;document.querySelector('#objective').textContent=wave===3?'Hold the courtyard':'Defeat the raiders'}
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.style.opacity=1;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.opacity=0,1150)}
function endGame(win){running=false;gameOver=true;document.querySelector('#modalTitle').textContent=win?'A knight is born.':'The keep has fallen.';document.querySelector('#modalText').textContent=win?`You drove back every raider and survived the Squire's Trial. Your name will be sung in the great hall.`:`You defeated ${kills} raiders before the courtyard was overrun. Take a breath, choose your weapon, and try again.`;document.querySelector('#start').textContent='PLAY AGAIN  →';document.querySelector('#modal').classList.remove('hidden')}
document.querySelector('#start').addEventListener('click',()=>{document.querySelector('#modal').classList.add('hidden');if(gameOver){for(const e of enemies)scene.remove(e.root);enemies=[];for(const a of arrows)scene.remove(a.mesh);arrows=[];player.hp=100;kills=0;wave=1;gameOver=false;player.root.position.set(0,0,5);player.root.rotation.y=0;updateHUD()}running=true;startWave()});
// Touch joystick
const stick=document.querySelector('#stick');let stickPointer=null;function touchMove(e){const r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),d=Math.min(34,len);move.x=dx/(len||1)*d/34;move.z=dy/(len||1)*d/34;stick.style.setProperty('--dx',`${move.x*34}px`);stick.style.setProperty('--dy',`${move.z*34}px`);stick.style.setProperty('background',`radial-gradient(circle at calc(50% + ${move.x*20}px) calc(50% + ${move.z*20}px),#d9c39a88 0 22px,#10182088 23px)`) }
stick.addEventListener('pointerdown',e=>{stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);touchMove(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)touchMove(e)});function resetStick(){stickPointer=null;move.x=move.z=0;stick.style.background=''}stick.addEventListener('pointerup',resetStick);stick.addEventListener('pointercancel',resetStick);
document.querySelector('[data-action="attack"]').addEventListener('pointerdown',e=>{e.preventDefault();attack()});document.querySelector('[data-action="dodge"]').addEventListener('pointerdown',e=>{e.preventDefault();dodge()});

