function frame(now){requestAnimationFrame(frame);const dt=Math.min(.04,(now-lastTime)/1000);lastTime=now;if(running&&!gameOver)tick(dt,now/1000);renderer.render(scene,camera)}requestAnimationFrame(frame);
function tick(dt,time){attackCooldown=Math.max(0,attackCooldown-dt);dodgeCooldown=Math.max(0,dodgeCooldown-dt);dodgeTimer=Math.max(0,dodgeTimer-dt);weaponSwing=Math.max(0,weaponSwing-dt);let ix=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+move.x,iz=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0)+move.z,len=Math.hypot(ix,iz);if(len>1){ix/=len;iz/=len}if(len>.05){player.root.rotation.y=Math.atan2(ix,iz);player.walk+=dt*10;player.body.position.y=Math.abs(Math.sin(player.walk))*.055;player.root.position.x+=ix*dt*(dodgeTimer?11:4.7);player.root.position.z+=iz*dt*(dodgeTimer?11:4.7)}player.root.position.x=clamp(player.root.position.x,-15.5,15.5);player.root.position.z=clamp(player.root.position.z,-13.5,13.2);const active=player.models[player.weaponType];active.rotation.z=weaponSwing>0?Math.sin((.38-weaponSwing)/.38*Math.PI)*-.95:0;if(player.weaponType==='flail'&&weaponSwing>0)active.rotation.x=Math.sin(time*22)*.35;
